/**
 * Convierte el esquema de AURORA de MySQL 8 a PostgreSQL 16.
 *
 * Se hace con un script y no a mano para que la conversion sea reproducible y
 * auditable: el capitulo 4 del documento declara el script relacional, y este
 * archivo explica como se llego de un motor al otro.
 *
 * Transformaciones aplicadas:
 *   AUTO_INCREMENT              -> GENERATED BY DEFAULT AS IDENTITY
 *   ENUM('a','b')               -> CREATE TYPE <tabla>_<columna> AS ENUM (...)
 *   TINYINT(1)                  -> BOOLEAN  (y DEFAULT 1/0 -> TRUE/FALSE)
 *   TINYINT                     -> SMALLINT
 *   DATETIME / TIMESTAMP        -> TIMESTAMPTZ
 *   ON UPDATE CURRENT_TIMESTAMP -> trigger set_actualizado_en()
 *   JSON                        -> JSONB
 *   INDEX / KEY en linea        -> CREATE INDEX aparte
 *   UNIQUE KEY en linea         -> CONSTRAINT ... UNIQUE
 *   FULLTEXT KEY                -> indice GIN sobre to_tsvector('spanish', ...)
 *   ENGINE=InnoDB               -> se elimina
 *
 * Las claves ajenas se extraen y se emiten al final con ALTER TABLE: asi el
 * orden de creacion de las tablas deja de importar (MySQL lo resolvia apagando
 * FOREIGN_KEY_CHECKS, que en Postgres no existe).
 */
import { readFileSync, writeFileSync } from 'node:fs'

const entrada = process.argv[2] ?? 'database/schema.mysql.sql'
const salida = process.argv[3] ?? 'database/schema.postgres.sql'

let sql = readFileSync(entrada, 'utf8').replace(/\r\n/g, '\n')

// --- 1. fuera lo que no existe en Postgres -----------------------------------
sql = sql
  .replace(/CREATE DATABASE[\s\S]*?;\n/gi, '')
  .replace(/^USE .*;\n/gim, '')
  .replace(/^SET FOREIGN_KEY_CHECKS.*;\n/gim, '')

// --- 2. recolectores ---------------------------------------------------------
const tipos = [] // CREATE TYPE ... AS ENUM
const tablas = [] // CREATE TABLE ya convertidas
const indices = [] // CREATE INDEX
const ajenas = [] // ALTER TABLE ... ADD CONSTRAINT ... FOREIGN KEY
const disparos = [] // CREATE TRIGGER
const booleanas = {} // tabla -> [columnas booleanas]  (lo usa el conversor del seed)
const enums = {} // tabla.columna -> nombre del tipo

const partirColumnas = (txt) =>
  txt
    .replace(/^\(|\)$/g, '')
    .split(',')
    .map((c) => c.trim())

const bloque = /CREATE TABLE (\w+) \(\n([\s\S]*?)\n\) ENGINE=InnoDB;/g
let m
while ((m = bloque.exec(sql)) !== null) {
  const tabla = m[1]
  const cuerpo = m[2]
  const lineas = []
  let columnaActualizada = null

  // Una definicion puede ocupar varias lineas fisicas (hay ENUM largos
  // partidos en dos). Se reagrupa por balance de parentesis antes de tocar
  // nada, contando sobre una copia sin comentarios para no contaminar.
  const logicas = []
  let buf = null
  for (const ln of cuerpo.split('\n')) {
    if (buf === null) {
      if (/^\s*--/.test(ln) || ln.trim() === '') {
        logicas.push(ln)
        continue
      }
      buf = ln
    } else {
      buf += ' ' + ln.trim()
    }
    const limpio = buf.replace(/\s--\s.*$/, '')
    const abre = (limpio.match(/\(/g) ?? []).length
    const cierra = (limpio.match(/\)/g) ?? []).length
    if (abre <= cierra) {
      logicas.push(buf)
      buf = null
    }
  }
  if (buf !== null) logicas.push(buf)

  for (const cruda of logicas) {
    // el comentario se conserva tal cual: documenta decisiones de modelado
    if (/^\s*--/.test(cruda) || cruda.trim() === '') {
      lineas.push(cruda)
      continue
    }

    let l = cruda
    const coma = /,\s*$/.test(l)
    l = l.replace(/,\s*$/, '')
    // un comentario al final de la linea se aparta y se vuelve a pegar despues
    const comentario = l.match(/\s+--\s.*$/)
    if (comentario) l = l.slice(0, comentario.index)

    const t = l.trim()

    // ---- lineas estructurales ----
    const fk = t.match(/^CONSTRAINT\s+(\w+)\s+FOREIGN KEY\s*(\([^)]*\))\s+REFERENCES\s+(.+)$/i)
    if (fk) {
      ajenas.push(
        `ALTER TABLE ${tabla} ADD CONSTRAINT ${fk[1]} FOREIGN KEY ${fk[2]} REFERENCES ${fk[3]};`
      )
      continue
    }

    const uk = t.match(/^UNIQUE KEY (\w+) (\([^)]*\))$/i)
    if (uk) {
      lineas.push(`  CONSTRAINT ${uk[1]} UNIQUE ${uk[2]}${coma ? ',' : ''}`)
      continue
    }

    const ft = t.match(/^FULLTEXT KEY (\w+) \(([^)]*)\)$/i)
    if (ft) {
      const expr = partirColumnas(`(${ft[2]})`)
        .map((c) => `coalesce(${c}, '')`)
        .join(" || ' ' || ")
      indices.push(
        `CREATE INDEX ${ft[1]} ON ${tabla} USING GIN (to_tsvector('spanish', ${expr}));`
      )
      continue
    }

    const ix = t.match(/^(?:INDEX|KEY) (\w+) (\([^)]*\))$/i)
    if (ix) {
      indices.push(`CREATE INDEX ${ix[1]} ON ${tabla} ${ix[2]};`)
      continue
    }

    if (/^(PRIMARY KEY|CONSTRAINT \w+ (CHECK|UNIQUE))/i.test(t)) {
      lineas.push(`  ${t}${coma ? ',' : ''}`)
      continue
    }

    // ---- definicion de columna ----
    const nombre = t.match(/^(\w+)/)?.[1] ?? ''
    let d = t

    // ENUM -> tipo propio. El nombre lleva tabla y columna para no chocar.
    const en = d.match(/ENUM\s*\(([^)]*)\)/i)
    if (en) {
      const tipo = `${tabla}_${nombre}`
      tipos.push(`CREATE TYPE ${tipo} AS ENUM (${en[1]});`)
      enums[`${tabla}.${nombre}`] = tipo
      d = d.replace(/ENUM\s*\([^)]*\)/i, tipo)
    }

    // TINYINT(1) es el booleano de MySQL; TINYINT suelto es un entero chico.
    if (/\bTINYINT\s*\(1\)/i.test(d)) {
      d = d
        .replace(/\bTINYINT\s*\(1\)/i, 'BOOLEAN')
        .replace(/\bDEFAULT\s+1\b/i, 'DEFAULT TRUE')
        .replace(/\bDEFAULT\s+0\b/i, 'DEFAULT FALSE')
      ;(booleanas[tabla] ??= []).push(nombre)
    } else {
      d = d.replace(/\bTINYINT(\s*\(\d+\))?/i, 'SMALLINT')
    }

    d = d
      .replace(
        /\b(BIG)?INT(\s*\(\d+\))?\s+AUTO_INCREMENT/i,
        (_s, big) => `${big ? 'BIGINT' : 'INT'} GENERATED BY DEFAULT AS IDENTITY`
      )
      .replace(/\bAUTO_INCREMENT\b/i, '')
      .replace(/\bDATETIME\b/i, 'TIMESTAMPTZ')
      .replace(/\bTIMESTAMP\b(?!TZ)/i, 'TIMESTAMPTZ')
      .replace(/\bJSON\b/i, 'JSONB')
      // Postgres tiene un solo TEXT, sin los tamanios de MySQL.
      .replace(/\b(TINY|MEDIUM|LONG)TEXT\b/i, 'TEXT')
      .replace(/\b(TINY|MEDIUM|LONG)?BLOB\b/i, 'BYTEA')
      .replace(/\bDOUBLE\b(?!\s+PRECISION)/i, 'DOUBLE PRECISION')
      // CHAR(n) en Postgres rellena con espacios hasta n, que no es la
      // semantica de MySQL. Para hashes y codigos de largo fijo da igual, pero
      // VARCHAR evita la sorpresa si alguna vez se guarda algo mas corto.
      .replace(/\bCHAR\s*\((\d+)\)/i, 'VARCHAR($1)')
      .replace(/\bMEDIUMINT\b/i, 'INT')

    // MySQL refresca la columna solo; en Postgres hace falta un trigger.
    if (/ON UPDATE CURRENT_TIMESTAMP/i.test(d)) {
      d = d.replace(/\s*ON UPDATE CURRENT_TIMESTAMP/i, '')
      columnaActualizada = nombre
    }
    d = d.replace(/\bCURRENT_TIMESTAMP\b/gi, 'now()').replace(/\s+/g, ' ')

    lineas.push(`  ${d}${coma ? ',' : ''}${comentario ? comentario[0] : ''}`)
  }

  // Al sacar del cuerpo las claves ajenas y los indices, la ultima definicion
  // que queda suele arrastrar la coma que la separaba de ellas. Se quita.
  for (let i = lineas.length - 1; i >= 0; i--) {
    const l = lineas[i]
    if (l.trim() === '' || /^\s*--/.test(l)) continue
    lineas[i] = l.replace(/,(\s*(--.*)?)$/, '$1')
    break
  }

  tablas.push(`CREATE TABLE ${tabla} (\n${lineas.join('\n')}\n);`)

  if (columnaActualizada) {
    disparos.push(
      `CREATE TRIGGER tg_${tabla}_actualizado BEFORE UPDATE ON ${tabla}\n` +
        `  FOR EACH ROW EXECUTE FUNCTION set_actualizado_en();`
    )
  }
}

// --- 3. las vistas pasan casi intactas ---------------------------------------
const vistas = [...sql.matchAll(/CREATE OR REPLACE VIEW[\s\S]*?;\n/gi)].map((v) => v[0].trim())

// --- 4. armado del archivo ---------------------------------------------------
const raya = '='.repeat(76)
const enc = (t) => `\n-- ${raya}\n-- ${t}\n-- ${raya}\n`

const fuera = [
  `-- ${raya}`,
  '--  AURORA  |  Sistema de comercio electronico multisucursal de ropa femenina',
  '--  Materia: SI2  -  Parcial 1',
  '--  Motor  : PostgreSQL 16',
  `-- ${raya}`,
  '--  GENERADO por scripts/mysql-a-postgres.mjs a partir de schema.mysql.sql.',
  '--  No editar a mano: editar el origen o el script y volver a generar.',
  `-- ${raya}`,
  '',
  'SET client_min_messages = WARNING;',
  '',
  enc('0. FUNCION DE APOYO: refresco automatico de actualizado_en'),
  'CREATE OR REPLACE FUNCTION set_actualizado_en() RETURNS trigger AS $func$',
  'BEGIN',
  '  NEW.actualizado_en = now();',
  '  RETURN NEW;',
  'END;',
  '$func$ LANGUAGE plpgsql;',
  enc(`1. TIPOS ENUMERADOS (${tipos.length})`),
  tipos.join('\n'),
  enc(`2. TABLAS (${tablas.length})`),
  tablas.join('\n\n'),
  enc(`3. CLAVES AJENAS (${ajenas.length})`),
  ajenas.join('\n'),
  enc(`4. INDICES (${indices.length})`),
  indices.join('\n'),
  enc(`5. DISPARADORES DE actualizado_en (${disparos.length})`),
  disparos.join('\n\n'),
  enc(`6. VISTAS DE APOYO PARA REPORTES (${vistas.length})`),
  vistas.join('\n\n'),
  '',
].join('\n')

writeFileSync(salida, fuera)
writeFileSync('database/columnas-booleanas.json', JSON.stringify(booleanas, null, 2))
writeFileSync('database/tipos-enum.json', JSON.stringify(enums, null, 2))

console.log(`tipos enum    : ${tipos.length}`)
console.log(`tablas        : ${tablas.length}`)
console.log(`claves ajenas : ${ajenas.length}`)
console.log(`indices       : ${indices.length}`)
console.log(`triggers      : ${disparos.length}`)
console.log(`vistas        : ${vistas.length}`)
console.log(`-> ${salida}`)
